# ================================================================================

def fitness_password_strength(chromosome, target):
    s = chromosome[0]
    len_s = len(s)
    has_digit = any(ch.isdigit() for ch in s)
    has_upper = any(ch.isupper() for ch in s)
    has_digit_int = 1 if has_digit else 0
    has_upper_int = 1 if has_upper else 0

    if target == "weak_short":
        return max(0, len_s - 5)
    elif target == "strong":
        fitness = 0
        fitness += max(0, 10 - len_s)
        fitness += (1 - has_digit_int)
        fitness += (1 - has_upper_int)
        return fitness
    elif target == "medium":
        fitness = 0
        fitness += max(0, 6 - len_s)
        if not (has_digit or has_upper):
            fitness += 1
        if len_s >= 10 and has_digit and has_upper:
            fitness += 1
        return fitness
    elif target == "weak_no_digit_upper":
        fitness = 0
        fitness += max(0, 6 - len_s)
        if has_digit:
            fitness += 1
        if has_upper:
            fitness += 1
        return fitness
    return float('inf')

