# ================================================================================

def fitness_string_category(chromosome, target):
    s = chromosome[0]
    current_len = len(s)

    is_palindrome = (s == s[::-1])

    # Branch distances for individual positive conditions (0 if condition met, >0 otherwise)
    bd_len_eq_0 = abs(current_len - 0)
    bd_s_is_palindrome = 0 if is_palindrome else 1
    bd_len_gt_3 = max(0, 3 - current_len + 1)
    bd_len_gt_5 = max(0, 5 - current_len + 1)

    # Branch distances for individual negative conditions or 'not met' conditions (0 if condition *not* met, >0 otherwise)
    bd_len_ne_0 = 1 if current_len == 0 else 0
    bd_s_is_not_palindrome = 0 if not is_palindrome else 1
    bd_len_le_3 = max(0, current_len - 3)
    bd_len_le_5 = max(0, current_len - 5)

    if target == "empty":
        # Path: len(s) == 0
        return bd_len_eq_0

    elif target == "long_palindrome":
        # Path: (len(s) != 0) AND (s == s[::-1]) AND (len(s) > 3)
        return bd_len_ne_0 + bd_s_is_palindrome + bd_len_gt_3

    elif target == "short_palindrome":
        # Path: (len(s) != 0) AND NOT (s == s[::-1] and len(s) > 3) AND (s == s[::-1])
        # NOT (s == s[::-1] and len(s) > 3) simplifies to (s != s[::-1] OR len(s) <= 3)
        bd_not_second_elif_cond = min(bd_s_is_not_palindrome, bd_len_le_3)
        return bd_len_ne_0 + bd_not_second_elif_cond + bd_s_is_palindrome

    elif target == "long_non_palindrome":
        # Path: (len(s) != 0) AND NOT (s == s[::-1] and len(s) > 3) AND NOT (s == s[::-1]) AND (len(s) > 5)
        # NOT (s == s[::-1]) simplifies to (s != s[::-1])
        bd_not_second_elif_cond = min(bd_s_is_not_palindrome, bd_len_le_3)
        return bd_len_ne_0 + bd_not_second_elif_cond + bd_s_is_not_palindrome + bd_len_gt_5

    elif target == "other":
        # Path: (len(s) != 0) AND NOT (s == s[::-1] and len(s) > 3) AND NOT (s == s[::-1]) AND NOT (len(s) > 5)
        # NOT (s == s[::-1]) simplifies to (s != s[::-1])
        # NOT (len(s) > 5) simplifies to (len(s) <= 5)
        bd_not_second_elif_cond = min(bd_s_is_not_palindrome, bd_len_le_3)
        return bd_len_ne_0 + bd_not_second_elif_cond + bd_s_is_not_palindrome + bd_len_le_5

    return 1000

