# Original function: list_score
# Fitness function: fitness_list_score
# Targets inferred by LLM: ['empty', 'high', 'medium', 'low']
# Notes: Generates fitness values for achieving specific return branches of 'list_score': 'empty' (list length is 0), 'high' (average > 10), 'medium' (average is between 0 and 10 inclusive), and 'low' (average < 0). Fitness is 0 if the target is met, otherwise a positive value representing the distance to satisfy the branch conditions.
# ================================================================================

def fitness_list_score(chromosome, target):
    nums = chromosome[0]
    length_nums = len(nums)

    if target == "empty":
        if length_nums == 0:
            return 0
        else:
            return float(length_nums)

    # For targets requiring calculations involving average, the list must not be empty
    if length_nums == 0:
        return 1.0 # Penalize for an empty list when other targets require a non-empty list

    total = sum(nums)
    avg = float(total) / length_nums

    if target == "high": # Condition: avg > 10
        if avg > 10:
            return 0
        else:
            # Distance for avg <= 10. We want avg to be greater than 10.
            return (10 - avg) + 1e-6

    elif target == "medium": # Condition: 0 <= avg <= 10
        if 0 <= avg <= 10:
            return 0
        else:
            fitness = 0.0
            # If avg is too high, push it down towards 10.
            if avg > 10:
                fitness += (avg - 10) + 1e-6
            # If avg is too low, push it up towards 0.
            if avg < 0:
                fitness += (0 - avg) + 1e-6
            return fitness

    elif target == "low": # Condition: avg < 0
        if avg < 0:
            return 0
        else:
            # Distance for avg >= 0. We want avg to be less than 0.
            return (avg - 0) + 1e-6

    return float('inf')

